; Letter highlight and the sounds of the name entry
; $4dc0-$4de2

; Highlights letter X of the letter row (colour RAM $db4e): the old letter $2f goes back to colour 4, letter X gets colour 1. Then waits. X does not change.
name_entry_highlight
        txa
        pha
        cmp temp2
        beq name_entry_highlight_wait
        ldx temp2                       ; The first call has $2f = $ff. It writes 4 to $dc4d, a mirror of the CIA 1 register $dc0d.
        lda #$04
        sta $db4e,x
        pla
        pha
        tax
        stx temp2
        lda #$01
        sta $db4e,x
name_entry_highlight_wait
        pla
        tax
        ldy #$3f
name_entry_highlight_delay
        inc tick
        bne name_entry_highlight_delay
        dey
        bne name_entry_highlight_delay
        rts
